function renumberFootnotes(){[...editor.querySelectorAll('.footnote-ref')].forEach((ref,index)=>{ref.textContent=`〔${index+1}〕`;ref.setAttribute('aria-label',`脚注 ${index+1}`);const row=footnoteList.querySelector(`[data-note-id="${CSS.escape(ref.dataset.noteId)}"]`);if(row){row.querySelector('.footnote-number').textContent=`${index+1}.`;footnoteList.append(row)}});updateStats()}
function addComment(){const range=selectedRange(false);if(!range){alert('请把光标放在正文中。');return}const note=prompt('按语或评论：','');if(!note)return;if(!range.collapsed)wrapSelection('comment-anchor',{comment:note});const p=document.createElement('p');p.className='comment-block';p.textContent=note;const paragraph=(range.startContainer.nodeType===1?range.startContainer:range.startContainer.parentElement).closest('p');(paragraph||editor.lastElementChild).after(p);savedRange=null;changed();addLog('插入按语',note)}
function clearFormatting(){const range=selectedRange(true);if(!range){alert('请选择要清除格式的文字。');return}const selected=range.toString();document.execCommand('removeFormat',false,null);savedRange=null;changed();addLog('清除所选格式',selected)}
function applyTextStyle(command,value,label){const range=selectedRange(true);if(!range){alert('请先选择正文中的文字。');return}const selected=range.toString();document.execCommand('styleWithCSS',false,true);const applied=document.execCommand(command,false,value??null);if(!applied){const span=document.createElement('span');if(command==='underline')span.style.textDecoration='underline';else if(command==='strikeThrough')span.style.textDecoration='line-through';else if(command==='hiliteColor')span.style.backgroundColor=value;else if(command==='bold')span.style.fontWeight='700';else{alert(`无法应用${label}。`);return}try{range.surroundContents(span)}catch{span.append(range.extractContents());range.insertNode(span)}}savedRange=null;changed();addLog(`设置${label}`,selected)}
