const MEDIA_DB_NAME='study-editor-media-v1',MEDIA_STORE='attachments',IMAGE_LIMIT=2*1024*1024,VIDEO_LIMIT=10*1024*1024,TOTAL_MEDIA_LIMIT=25*1024*1024;let mediaRecords=new Map(),draftMediaIds=[];
async function loadMediaRecords(){renderAnnotationRegisters();renderNotes();renderDraftMedia();renderInlineMedia()}
async function putMedia(record){mediaRecords.set(record.id,record)}
async function deleteMedia(id){mediaRecords.delete(id)}
function mediaIds(element){try{return JSON.parse(element?.dataset.mediaIds||'[]')}catch{return[]}}
function setMediaIds(element,ids){element.dataset.mediaIds=JSON.stringify(ids)}
function mediaTotal(){return [...mediaRecords.values()].reduce((sum,item)=>sum+item.size,0)}
async function normalizeImage(file){const bitmap=await createImageBitmap(file),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));if(scale===1&&file.size<=IMAGE_LIMIT){bitmap.close();return file}const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.86));return new File([blob],file.name.replace(/\.[^.]+$/,'.webp'),{type:'image/webp'})}
async function prepareMedia(file){if(!file.type.startsWith('image/')&&!['video/mp4','video/webm'].includes(file.type))throw new Error(`不支持的媒体格式：${file.type||file.name}`);const prepared=file.type.startsWith('image/')?await normalizeImage(file):file,limit=prepared.type.startsWith('image/')?IMAGE_LIMIT:VIDEO_LIMIT;if(prepared.size>limit)throw new Error(`${prepared.type.startsWith('image/')?'图片':'视频'}超过大小限制。`);if(mediaTotal()+prepared.size>TOTAL_MEDIA_LIMIT)throw new Error('本篇媒体总量将超过 25 MB。');return prepared}
async function addMediaFiles(files){const ids=[];for(const original of files){const file=await prepareMedia(original),id=crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`,record={id,storageKey:STORAGE_KEY,name:file.name||'粘贴媒体',type:file.type,size:file.size,blob:file};await putMedia(record);ids.push(id)}return ids}
function renderMediaStrip(container,ids,onRemove){container.innerHTML='';ids.forEach(id=>{const record=mediaRecords.get(id);if(!record)return;const item=document.createElement('div');item.className='media-item';const media=document.createElement(record.type.startsWith('image/')?'img':'video');media.src=URL.createObjectURL(record.blob);media.title=record.name;if(media.tagName==='VIDEO')media.controls=true;media.onload=media.onloadeddata=()=>URL.revokeObjectURL(media.src);const label=document.createElement('small');label.textContent=`${record.name} · ${(record.size/1024/1024).toFixed(1)} MB`;const remove=document.createElement('button');remove.type='button';remove.className='media-remove';remove.textContent='×';remove.title='移除媒体';remove.onclick=async()=>{await deleteMedia(id);onRemove(id)};item.append(media,label,remove);container.append(item)})}
async function attachFilesToElement(files,element,container){try{const ids=[...mediaIds(element),...await addMediaFiles(files)];setMediaIds(element,ids);renderMediaStrip(container,ids,id=>{setMediaIds(element,mediaIds(element).filter(value=>value!==id));renderAnnotationRegisters();changed()});changed()}catch(error){alert(error.message)}}
function enableMediaOnArea(area,element,container,actions){area.addEventListener('paste',async event=>{const files=[...event.clipboardData.files];if(!files.length)return;event.preventDefault();await attachFilesToElement(files,element,container)});const add=document.createElement('button'),input=document.createElement('input');add.type='button';add.className='media-add';add.textContent='添加媒体';input.type='file';input.multiple=true;input.accept='image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm';input.className='hidden';add.onclick=()=>input.click();input.onchange=async()=>{await attachFilesToElement([...input.files],element,container);input.value=''};actions.append(add,input);renderMediaStrip(container,mediaIds(element),id=>{setMediaIds(element,mediaIds(element).filter(value=>value!==id));renderAnnotationRegisters();changed()})}
function fileToDataUrl(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)})}
async function exportMedia(){return Promise.all([...mediaRecords.values()].map(async item=>({id:item.id,name:item.name,type:item.type,size:item.size,dataUrl:await fileToDataUrl(item.blob)})))}
async function importMedia(items=[]){for(const item of items){const match=String(item.dataUrl).match(/^data:([^;,]+);base64,([A-Za-z0-9+/=]+)$/);if(!match||!['image/png','image/jpeg','image/webp','image/gif','video/mp4','video/webm'].includes(match[1]))throw Error('Unsupported attachment');const bytes=Uint8Array.from(atob(match[2]),c=>c.charCodeAt(0)),blob=new Blob([bytes],{type:match[1]});await putMedia({id:item.id,storageKey:STORAGE_KEY,name:item.name,type:item.type,size:blob.size,blob})}}
function createInlineFigure(id,name=''){const figure=document.createElement('figure');figure.className='inline-media';figure.dataset.mediaId=id;figure.dataset.size='medium';figure.contentEditable='false';const img=document.createElement('img');img.dataset.mediaId=id;img.alt=name;const caption=document.createElement('figcaption');caption.contentEditable='true';caption.dataset.placeholder='图片说明（可选）';caption.setAttribute('aria-label','图片说明');const tools=document.createElement('div');tools.className='inline-media-tools';tools.contentEditable='false';figure.append(img,caption,tools);return figure}
function renderInlineMedia(){editor.querySelectorAll('.inline-media[data-media-id]').forEach(figure=>{const id=figure.dataset.mediaId,record=mediaRecords.get(id),img=figure.querySelector('img')||document.createElement('img');if(!record)return;if(!img.isConnected)figure.prepend(img);img.dataset.mediaId=id;img.alt=img.alt||record.name;const url=URL.createObjectURL(record.blob);img.src=url;img.onload=()=>URL.revokeObjectURL(url);let tools=figure.querySelector('.inline-media-tools');if(!tools){tools=document.createElement('div');tools.className='inline-media-tools';tools.contentEditable='false';figure.append(tools)}tools.innerHTML='';[['small','小'],['medium','中'],['large','大'],['full','全宽']].forEach(([size,label])=>{const button=document.createElement('button');button.type='button';button.textContent=label;button.classList.toggle('active',(figure.dataset.size||'medium')===size);button.onclick=()=>{figure.dataset.size=size;renderInlineMedia();changed()};tools.append(button)});const remove=document.createElement('button');remove.type='button';remove.textContent='删除图片';remove.onclick=async()=>{if(!confirm('删除这张正文图片？'))return;await deleteMedia(id);figure.remove();changed()};tools.append(remove)})}
async function insertInlineImage(file,range=savedRange?.cloneRange()){try{if(!file?.type.startsWith('image/'))throw new Error('请选择图片文件。');const [id]=await addMediaFiles([file]),record=mediaRecords.get(id),figure=createInlineFigure(id,record?.name||file.name);const start=range?.startContainer,startElement=start?.nodeType===Node.ELEMENT_NODE?start:start?.parentElement,anchor=startElement?.closest?.('#editor > p,#editor > figure');if(anchor)anchor.after(figure);else editor.append(figure);renderInlineMedia();figure.scrollIntoView({behavior:'smooth',block:'center'});savedRange=null;changed();addLog('插入正文图片',record?.name||file.name)}catch(error){alert(error.message)}}
function editorStateHtml(){const clone=editor.cloneNode(true);clone.querySelectorAll('.inline-media img').forEach(img=>img.removeAttribute('src'));return clone.innerHTML}
