function mergeInitialNotes(){const notes=getStored(NOTES_KEY),seen=new Set(notes.map(item=>`${item.time}\u0000${item.text}`));let changed=false;INITIAL_READING_NOTES.forEach(item=>{const key=`${item.time}\u0000${item.text}`;if(!seen.has(key)){notes.push(item);seen.add(key);changed=true}});if(changed)localStorage.setItem(NOTES_KEY,JSON.stringify(notes.sort((a,b)=>String(b.time).localeCompare(String(a.time)))))}
