function state(){return{version:4,savedAt:new Date().toISOString(),bodyHTML:editorStateHtml(),terms:TERMS,footnotes:[...footnoteList.querySelectorAll('.footnote-item')].map(row=>({id:row.dataset.noteId,note:row.querySelector('textarea').value,mediaIds:mediaIds(row)})),notes:getStored(NOTES_KEY),log:getStored(LOG_KEY)}}
function loadState(data){editor.innerHTML=data.bodyHTML||initialHTML;if(Array.isArray(data.terms)){data.terms.forEach(saved=>{const term=TERMS.find(item=>item.term===saved.term);if(term){term.pinyin=saved.pinyin??term.pinyin;term.annotation=saved.annotation??term.annotation}})}footnoteList.innerHTML='';(data.footnotes||[]).forEach(item=>addFootnoteRow(item.id,item.note,item.mediaIds||[]));if(Array.isArray(data.notes))localStorage.setItem(NOTES_KEY,JSON.stringify(data.notes));if(Array.isArray(data.log))localStorage.setItem(LOG_KEY,JSON.stringify(data.log));mergeInitialNotes();renumberFootnotes();renderTerms(document.getElementById('termSearch').value);renderNotes();renderLog();renderAnnotationRegisters();updateStats()}
