function cleanSpeechFragment(fragment){fragment.querySelectorAll?.('rt,.inline-gloss,.comment-block,.footnote-ref,.inline-media').forEach(node=>node.remove());return (fragment.textContent||'').replace(/\s+/g,' ').trim()}
