document.addEventListener('selectionchange',rememberSelection);editor.addEventListener('input',changed);editor.addEventListener('click',event=>{const footnote=event.target.closest('.footnote-ref');if(footnote){locateFootnoteRow(footnote.dataset.noteId);return}const globalAnchor=event.target.closest('.global-term-anchor');if(globalAnchor&&!globalAnchor.classList.contains('difficulty-filtered')&&!document.body.classList.contains('global-hints-off')){showGlobalDictionaryTerm(globalAnchor.dataset.globalTerm);return}if(document.body.classList.contains('annotated-view')){const anchor=event.target.closest('.term-anchor'),notation=anchor?.closest('.notation');if(notation)jumpToDictionaryTerm(notation.dataset.term||notationTerm(notation))}});editor.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){const globalAnchor=event.target.closest('.global-term-anchor');if(globalAnchor&&!globalAnchor.classList.contains('difficulty-filtered')&&!document.body.classList.contains('global-hints-off')){event.preventDefault();showGlobalDictionaryTerm(globalAnchor.dataset.globalTerm);return}if(document.body.classList.contains('annotated-view')){const anchor=event.target.closest('.term-anchor'),notation=anchor?.closest('.notation');if(notation){event.preventDefault();jumpToDictionaryTerm(notation.dataset.term||notationTerm(notation))}}}});editor.addEventListener('paste',async event=>{const image=[...event.clipboardData.files].find(file=>file.type.startsWith('image/'));if(image){event.preventDefault();await insertInlineImage(image);return}event.preventDefault();document.execCommand('insertText',false,event.clipboardData.getData('text/plain'))});
