document.getElementById('globalDefinition').onclick=event=>{const edit=event.target.closest('#editGlobalTermBtn');if(edit){editGlobalDictionaryTerm(edit.dataset.term);return}const form=event.target.closest('#globalTermEditForm');if(!form)return;if(event.target.closest('#cancelGlobalTermEdit'))showGlobalDictionaryTerm(form.dataset.term);else if(event.target.closest('#resetGlobalTermEdit')&&confirm(`恢复“${form.dataset.term}”的词典原值？`))resetGlobalDictionaryTerm(form.dataset.term)};
document.getElementById('globalDefinition').onsubmit=event=>{if(event.target.id!=='globalTermEditForm')return;event.preventDefault();const form=event.target,entry=GLOBAL_TERMS.find(item=>item.term===form.dataset.term);if(!entry)return;const values=new FormData(form);entry.pinyin=String(values.get('pinyin')||'').trim();entry.difficulty=String(Number(values.get('difficulty'))||3);entry.annotation=String(values.get('definition')||'').trim();persistGlobalDictionaryTerm(entry);ensureGlobalDictionaryHints();showGlobalDictionaryTerm(entry.term);addLog('编辑全书词典',`${entry.term}：Level ${entry.difficulty}`)};
const formatMenu=document.getElementById('formatMenu'),formatMenuBtn=document.getElementById('formatMenuBtn');function closeFormatMenu(){formatMenu.classList.remove('open');formatMenuBtn.setAttribute('aria-expanded','false')}formatMenuBtn.onclick=event=>{event.stopPropagation();const opening=!formatMenu.classList.contains('open');closeFormatMenu();if(opening){formatMenu.classList.add('open');formatMenuBtn.setAttribute('aria-expanded','true')}};document.getElementById('formatPopover').onclick=event=>{const option=event.target.closest('.format-option');if(!option)return;applyTextStyle(option.dataset.command,option.dataset.value||null,option.dataset.label);closeFormatMenu()};document.addEventListener('click',event=>{if(!formatMenu.contains(event.target))closeFormatMenu()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeFormatMenu()});document.getElementById('boldBtn').onclick=()=>applyTextStyle('bold',null,'粗体');
document.getElementById('notationBtn').onclick=()=>addNotation();document.getElementById('interlinearBtn').onclick=()=>{addInterlinearNote();renderAnnotationRegisters()};document.getElementById('footnoteBtn').onclick=addFootnote;document.getElementById('commentBtn').onclick=()=>{addComment();renderAnnotationRegisters()};document.getElementById('insertImageBtn').onclick=()=>document.getElementById('inlineImageInput').click();document.getElementById('inlineImageInput').onchange=async event=>{const file=event.target.files[0];if(file)await insertInlineImage(file);event.target.value=''};document.getElementById('doubtBtn').onclick=()=>{const note=prompt('待核原因（可留空）：','')||'';wrapSelection('doubt',{issue:note});renderAnnotationRegisters()};document.getElementById('clearBtn').onclick=()=>{clearFormatting();renderAnnotationRegisters()};
document.getElementById('saveBtn').onclick=()=>saveLocal(false);document.getElementById('printPdfBtn').onclick=exportPdf;document.getElementById('exportTxtBtn').onclick=()=>download('reader-notes_clean_edited.txt','text/plain;charset=utf-8',plainText());document.getElementById('exportJsonBtn').onclick=async()=>{const data=state();data.media=await exportMedia();download('reader-notes_editor_backup.json','application/json',JSON.stringify(data,null,2))};document.getElementById('exportHtmlBtn').onclick=()=>download('reader-notes_edited.html','text/html;charset=utf-8',exportStandalone());
document.getElementById('exportLogBtn').onclick=()=>{download('reader-notes_edit_log.txt','text/plain;charset=utf-8',getStored(LOG_KEY).map(item=>`${item.time}\t${item.action}\t${visibleLogDetail(item)}`).join('\n')+'\n');addLog('导出编辑日志')};
async function attachDraftFiles(files){try{draftMediaIds.push(...await addMediaFiles(files));renderDraftMedia()}catch(error){alert(error.message)}};document.getElementById('addUserNoteMediaBtn').onclick=()=>document.getElementById('userNoteMediaInput').click();document.getElementById('userNoteMediaInput').onchange=async event=>{await attachDraftFiles([...event.target.files]);event.target.value=''};document.getElementById('userNoteInput').addEventListener('paste',async event=>{const files=[...event.clipboardData.files];if(!files.length)return;event.preventDefault();await attachDraftFiles(files)});document.getElementById('addUserNoteBtn').onclick=()=>{const input=document.getElementById('userNoteInput'),text=input.value.trim();if(!text&&!draftMediaIds.length)return;const notes=getStored(NOTES_KEY);notes.unshift({time:new Date().toISOString(),text,mediaIds:[...draftMediaIds]});localStorage.setItem(NOTES_KEY,JSON.stringify(notes));input.value='';draftMediaIds=[];renderDraftMedia();renderNotes();addLog('添加用户札记')};
document.getElementById('exportNotesBtn').onclick=()=>download('reader-notes_reading_notes.txt','text/plain;charset=utf-8',getStored(NOTES_KEY).map(item=>`${item.time}\t${item.text}`).join('\n')+'\n');
document.getElementById('clearLogBtn').onclick=()=>{if(confirm('清空本浏览器保存的编辑日志？')){localStorage.removeItem(LOG_KEY);renderLog()}};
document.getElementById('importJson').onchange=event=>{const file=event.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=async()=>{try{const data=JSON.parse(reader.result);await importMedia(data.media||[]);loadState(data);saveLocal(false);renderNotes();renderAnnotationRegisters()}catch(error){alert('无法导入备份：'+error.message)}};reader.readAsText(file)};
document.getElementById('resetBtn').onclick=()=>{if(confirm('恢复初始文本会清除当前浏览器内的编辑记录。确定继续吗？')){localStorage.removeItem(STORAGE_KEY);editor.innerHTML=initialHTML;footnoteList.innerHTML='';INITIAL_FOOTNOTES.forEach(item=>addFootnoteRow(item.id,item.note,item.mediaIds||[]));renumberFootnotes();renderAnnotationRegisters();changed()}};
document.getElementById('termSearch').oninput=event=>renderTerms(event.target.value);document.getElementById('termList').onclick=event=>{const row=event.target.closest('.term');if(!row)return;const index=Number(row.dataset.index);if(event.target.closest('.edit-term'))editDictionaryTerm(index);else addNotation(TERMS[index])};document.getElementById('exportTermsBtn').onclick=exportTerms;
document.getElementById('speakBtn').onclick=speak;document.getElementById('pauseBtn').onclick=event=>{if(speechSynthesis.paused){speechSynthesis.resume();event.target.textContent='暂停'}else{speechSynthesis.pause();event.target.textContent='继续'}};document.getElementById('stopBtn').onclick=()=>speechSynthesis.cancel();document.getElementById('rate').oninput=event=>document.getElementById('rateValue').textContent=`${event.target.value}×`;window.addEventListener('resize',()=>footnoteList.querySelectorAll('textarea').forEach(resizeFootnoteTextarea));
speechSynthesis.onvoiceschanged=loadVoices;loadVoices();renderTerms();mergeInitialNotes();renderNotes();renderLog();const stored=localStorage.getItem(STORAGE_KEY);if(stored){try{loadState(JSON.parse(stored));saveStatus.textContent='已恢复浏览器中的编辑记录'}catch{localStorage.removeItem(STORAGE_KEY)}}else{INITIAL_FOOTNOTES.forEach(item=>addFootnoteRow(item.id,item.note,item.mediaIds||[]));renumberFootnotes()}mergeInitialNotes();renderNotes();applyProjectDictionaryOverrides();document.getElementById('difficultyLevel').value=localStorage.getItem(STORAGE_KEY+'-difficulty')||'3';const requestedView=new URLSearchParams(location.search).get('view');setView(['annotated','clean'].includes(requestedView)?requestedView:(sessionStorage.getItem('shiji-editor-view')||'clean'));setToolbarCollapsed(sessionStorage.getItem('shiji-toolbar-collapsed')==='yes');if(sessionStorage.getItem('shiji-global-hints')==='off')document.getElementById('globalHintsBtn').click();updateStats();importMedia(INITIAL_MEDIA).then(loadMediaRecords).catch(error=>console.error('无法载入媒体附件',error));